update public.venture_brand_kits set palette = '{"mode": "light", "name": "Tricolore", "version": 3, "source": "user-directed", "rationale": "Bleu, blanc, rouge — the French flag read as an institution''s identity, not as decoration. French Bleu #0055A4 carries structure, headline and primary action. A darkened flag navy #002654 anchors footers and institutional surfaces. French Rouge #EF4135 is the single act of emphasis on any given screen. White is the third stripe and the dominant surface, so the flag is present even where no colour is printed.", "colors": {"primary": "#0055A4", "onPrimary": "#FFFFFF", "secondary": "#002654", "onSecondary": "#FFFFFF", "accent": "#EF4135", "onAccent": "#0B0F19", "accentDeep": "#C8102E", "onAccentDeep": "#FFFFFF", "bg": "#FFFFFF", "surface": "#F4F6F9", "fg": "#1A1D23", "muted": "#5A6472", "border": "#DCE1E8"}, "usage": {"bleu": "Headlines, primary buttons, navigation, rules. White text on top.", "blanc": "The dominant surface, treated as a brand colour rather than an absence. Panels drop to #F4F6F9 so white stays deliberate.", "rouge": "One act of emphasis per screen: a fill, a rule, an icon, a single callout. Never body copy and never small text — white on #EF4135 is 3.8:1 and fails AA. For a red button carrying white text, use accentDeep #C8102E.", "forbidden": "Never place bleu, blanc and rouge as three equal vertical stripes in a UI or a mark — that is the flag, not the brand."}, "audit": [{"field": "primary", "from": "#0A2463", "to": "#0055A4", "reason": "Moved to the official French flag blue at the founder''s direction."}, {"field": "secondary", "from": "#C8A2C8", "to": "#002654", "reason": "Lilac pulled the identity away from the flag; replaced with a darkened French navy for institutional surfaces."}, {"field": "accent", "from": "#E63946", "to": "#EF4135", "reason": "Moved to the official French flag red."}, {"field": "bg", "from": "#F5F5F5", "to": "#FFFFFF", "reason": "Blanc is the third stripe and must read as pure white; panels use #F4F6F9."}, {"field": "onAccent", "from": "#FFFFFF", "to": "#0B0F19", "reason": "White on flag rouge is 3.8:1 and fails AA; dark ink passes at 5.0:1, and accentDeep #C8102E is provided for white-on-red."}], "contrast": {"pass": true, "pairings": [{"label": "Body text on background", "fg": "#1A1D23", "bg": "#FFFFFF", "required": 4.5, "ratio": 16.882, "pass": true}, {"label": "Muted text on background", "fg": "#5A6472", "bg": "#FFFFFF", "required": 3, "ratio": 5.999, "pass": true}, {"label": "Body text on panel surface", "fg": "#1A1D23", "bg": "#F4F6F9", "required": 4.5, "ratio": 15.593, "pass": true}, {"label": "Primary button label", "fg": "#FFFFFF", "bg": "#0055A4", "required": 4.5, "ratio": 7.406, "pass": true}, {"label": "Secondary button label", "fg": "#FFFFFF", "bg": "#002654", "required": 4.5, "ratio": 14.944, "pass": true}, {"label": "Accent label on flag rouge", "fg": "#0B0F19", "bg": "#EF4135", "required": 4.5, "ratio": 4.995, "pass": true}, {"label": "White label on deep rouge", "fg": "#FFFFFF", "bg": "#C8102E", "required": 4.5, "ratio": 5.883, "pass": true}]}}'::jsonb,
 art_direction = to_jsonb('The Friendship House is a Franco-American integration institution in Chateau-Thierry. Every generated image is art-directed to the French tricolour: French Bleu #0055A4, pure white, French Rouge #EF4135, with deep navy #002654 for weight. Shoot French civic warmth, not tourism: Chateau-Thierry stone facades, painted shutters, a real doorway and its enamel numberplate, a mairie in flat morning light, a shared table with mixed French and American company, prefecture paperwork photographed with respect, and blue-white-red carried as MATERIAL — enamel plaque, painted wood, linen, printed card — rather than as a waving flag. One tile at most may show an actual flag. Colour discipline: sample the exact three hexes; let white dominate; use rouge as a single accent per frame. Hard bans: no Eiffel Tower, no Arc de Triomphe, no berets, baguettes or wine cliches, no waving-flag stock photography, no US and French flag mashups or handshakes, no gradients, no lens flare, no readable text or lettering, no AI sheen.'::text),
 updated_at = now()
where snapshot_id = '0ca32be1-45d3-46bc-992e-dffa342d26bd';

update public.venture_snapshots
set brand_tokens = coalesce(brand_tokens, '{}'::jsonb) || jsonb_build_object('colors', jsonb_build_object('primary','#0055A4','secondary','#002654','accent','#EF4135','bg','#FFFFFF','fg','#1A1D23'))
where id = '0ca32be1-45d3-46bc-992e-dffa342d26bd';